sys_script_include.script:
var ATFBuilder = Class.create();
ATFBuilder.prototype = {

    initialize: function(storyName, storySysId) {
        this.storyName  = storyName;
        this.storySysId = storySysId;
    },

    /**
     * Build full ATF hierarchy from LLM-generated step definitions.
     * @param  {Array}  stepDefs  Array of { step_type, action, inputs, expected }
     * @returns {{ suiteId: string, testId: string }}
     */
    build: function(stepDefs) {
        if (!GlidePluginManager.isActive('com.snc.test_management2')) {
            throw new Error('ATF plugin (com.snc.test_management2) is not active on this instance.');
        }

        var suiteId = this._createSuite();
        var testId  = this._createTest(suiteId);
        this._createSteps(testId, stepDefs);

        return { suiteId: suiteId, testId: testId };
    },

    // ─── Suite ────────────────────────────────────────────────────────────────

    _createSuite: function() {
        var gr = new GlideRecord('sys_atf_suite');
        gr.initialize();
        gr.setValue('name',        'AI Generated: ' + this.storyName);
        gr.setValue('description', 'Auto-generated by SDLC AI Orchestrator for story ' + this.storySysId);
        gr.setValue('active',      true);
        var id = gr.insert();
        if (!id) {
            throw new Error('Failed to insert sys_atf_suite record.');
        }
        return id;
    },

    // ─── Test ─────────────────────────────────────────────────────────────────

    _createTest: function(suiteId) {
        var gr = new GlideRecord('sys_atf_test');
        gr.initialize();
        gr.setValue('name',        'AI Test: ' + this.storyName);
        gr.setValue('description', 'Auto-generated acceptance test from Gherkin criteria');
        gr.setValue('active',      true);
        gr.setValue('suite',       suiteId);
        var id = gr.insert();
        if (!id) {
            throw new Error('Failed to insert sys_atf_test record.');
        }
        return id;
    },

    // ─── Steps ────────────────────────────────────────────────────────────────

    _createSteps: function(testId, stepDefs) {
        if (!stepDefs || !stepDefs.length) return;

        for (var i = 0; i < stepDefs.length; i++) {
            var def      = stepDefs[i];
            var configId = this._resolveStepConfig(def.step_type, def.action);
            if (!configId) {
                gs.log('[ATFBuilder] Could not resolve step config for step_type=' + def.step_type + ' action=' + def.action + ' — skipping.', 'x_snc_ai_sdlc');
                continue;
            }

            var gr = new GlideRecord('sys_atf_step');
            gr.initialize();
            gr.setValue('test',             testId);
            gr.setValue('step_config',      configId);
            gr.setValue('order',            (i + 1) * 100);
            gr.setValue('active',           true);
            gr.setValue('inputs',           JSON.stringify(def.inputs   || {}));
            gr.setValue('expected_outputs', JSON.stringify(def.expected || {}));
            gr.insert();
        }
    },

    // ─── Step Config Lookup ───────────────────────────────────────────────────

    _resolveStepConfig: function(stepType, action) {
        var key = (stepType || '') + '.' + (action || '');

        var configMap = {
            'form.open':               'sn_atf.open_form',
            'form.set_field_value':    'sn_atf.set_field_values',
            'form.assert_field_value': 'sn_atf.assert_field_values',
            'form.submit':             'sn_atf.submit_form',
            'server.run_script':       'sn_atf.run_server_side_script',
            'rest.call':               'sn_atf.rest_step'
        };

        var configName = configMap[key];
        if (!configName) {
            var fallbacks = {
                'form':   'sn_atf.set_field_values',
                'server': 'sn_atf.run_server_side_script',
                'rest':   'sn_atf.rest_step'
            };
            configName = fallbacks[stepType];
        }
        if (!configName) return null;

        var gr = new GlideRecord('sys_atf_step_config');
        gr.addQuery('sys_name', configName);
        gr.setLimit(1);
        gr.query();
        return gr.next() ? gr.getUniqueValue() : null;
    },

    type: 'ATFBuilder'
};
